"""
Shared data-loading helper for the v2 reanalysis scripts (see README.md for context).

This module contains NO hardcoded path to any real-athlete dataset and NO real biomarker
values. By default, every script in this folder loads `database/dataset_real_world_example.csv`
-- the synthetic, privacy-safe demonstration dataset already generated by
`utils/generate_real_world_seed.py` -- which lets the pipeline's logic run end-to-end without
exposing real athlete data. It reproduces the STRUCTURE of the real n=22 cohort used in the
manuscript, not its numbers (see Section 7, Data Availability Statement, of the revised
manuscript, and the note at the top of README.md).

To run this pipeline against a different (e.g. real, non-public) dataset with the same column
structure, pass an explicit path: `python step_x.py --data-path /path/to/your/file.csv`.
This script never assumes or hardcodes where that file lives.
"""
import argparse
import os
import unicodedata
import numpy as np
import pandas as pd

# Resolved relative to this file's location (repo_root/notebooks/v2_reanalysis/common.py),
# NOT relative to the current working directory -- so the default works whether scripts are
# invoked from the repo root or from within this folder.
_REPO_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
DEFAULT_DATA_PATH = os.path.join(_REPO_ROOT, "database", "dataset_real_world_example.csv")

# Column-name aliases: the real cohort's source spreadsheet and the public synthetic generator
# use slightly different capitalization/spelling for the same biomarker-timepoint. Each entry
# lists every known variant; the loader picks whichever is present in the given file.
COLUMN_ALIASES = {
    "CK_Pre": ["CPK pré (u/L)", "CPK Pré (U/L)"],
    "CK_Pos": ["CPK pós (u/L)", "CPK Pós (U/L)"],
    "CK_24h": ["CPK 24h (u/L)", "CPK 24h (U/L)"],
    "LDH_Pre": ["LDH pre (u/L)", "LDH Pré (U/L)"],
    "LDH_Pos": ["LDH pós (u/L)", "LDH Pós (U/L)"],
    "LDH_24h": ["LDH 24h (u/L)", "LDH 24h (U/L)"],
    "CRP_Pre": ["PCR pré (mg/L)", "PCR Pré (mg/L)"],
    "CRP_Pos": ["PCR pós (mg/L)", "PCR Pós (mg/L)"],
    "CRP_24h": ["PCR 24h pós (mg/L)", "PCR 24h (mg/L)"],
    "Cortisol_Pre": ["Cortisol pre (u/L)", "Cortisol Pré (µg/dL)"],
    "Cortisol_Pos": ["Cortisol pós (ug/dL)", "Cortisol Pós (µg/dL)"],
    "Cortisol_24h": ["Cortisol 24h", "Cortisol 24h (µg/dL)"],
    "Testo_Pre": ["Testosterona T pré (nmol/L)", "Testosterona T Pré (nmol/L)"],
    "Testo_Pos": ["Testosterona T pós (nmol/L)", "Testosterona T Pós (nmol/L)"],
    "Testo_24h": ["Testosterona 24h (nmol/L)"],
    "RestingHR": ["FC Repouso (bpM)", "FC Repouso (bpm)"],
    "BloodPressure": ["Pressão (mmHG)"],
    "SpO2": ["Oximetria (SpO2)"],
}


def get_arg_parser(description):
    p = argparse.ArgumentParser(description=description)
    p.add_argument("--data-path", default=DEFAULT_DATA_PATH,
                    help=f"Path to the input CSV (default: {DEFAULT_DATA_PATH}, the public "
                         f"synthetic demo dataset). Point this at a real cohort file with the "
                         f"same column structure to reproduce the manuscript's actual analysis "
                         f"-- no such path is hardcoded anywhere in this repository.")
    return p


def _to_float(s):
    return pd.to_numeric(s.astype(str).str.replace(",", "."), errors="coerce")


def _resolve(df, canonical):
    for candidate in COLUMN_ALIASES[canonical]:
        if candidate in df.columns:
            return candidate
    raise KeyError(f"None of the known column-name variants for '{canonical}' "
                    f"({COLUMN_ALIASES[canonical]}) were found in the input file. "
                    f"Check --data-path and the column names of that file.")


def load_cohort(data_path):
    """
    Loads a biomarker cohort CSV (real or the public synthetic demo) and returns a numeric
    feature matrix with standardized column names, matching the preprocessing already used in
    notebooks/01_Phase1_RealWorld_SmallSample_HCA.ipynb (comma-decimal handling, blood-pressure
    splitting, median imputation of missing values).
    """
    raw = pd.read_csv(data_path)
    resolved = {canonical: _resolve(raw, canonical) for canonical in COLUMN_ALIASES}

    out = pd.DataFrame(index=raw.index)
    for canonical, col in resolved.items():
        if canonical == "BloodPressure":
            continue
        out[canonical] = _to_float(raw[col]) if raw[col].dtype == object else raw[col]

    bp_col = resolved["BloodPressure"]
    if raw[bp_col].dtype == object:
        temp = raw[bp_col].astype(str).str.split("/", expand=True)
        out["BP_Systolic"] = pd.to_numeric(temp[0], errors="coerce")
    else:
        out["BP_Systolic"] = raw[bp_col]

    out = out.fillna(out.median())
    return out, raw
